PREFIX dbo: <http://dbpedia.org/ontology/> 
PREFIX dbp: <http://dbpedia.org/property/> 
PREFIX dbr: <http://dbpedia.org/resource/> 
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?film ?filmLabel ?director ?directorLabel ?earliestBirth WHERE {
  VALUES ?film { dbr:Leave_It_to_Henry dbr:The_Last_Night_of_Scheherazade }
  {
    SELECT ?film (MIN(?birthDate) AS ?earliestBirth) WHERE {
      ?film dbo:director ?director .
      OPTIONAL { ?director dbo:birthDate ?bd1. }
      OPTIONAL { ?director dbp:birth_date ?bd2. }
      BIND(coalesce(?bd1, ?bd2) AS ?birthDate)
      FILTER(bound(?birthDate))
      VALUES ?film { dbr:Leave_It_to_Henry dbr:The_Last_Night_of_Scheherazade }
    } GROUP BY ?film
  }
  ?film dbo:director ?director .
  OPTIONAL { ?director dbo:birthDate ?bd1. }
  OPTIONAL { ?director dbp:birth_date ?bd2. }
  BIND(coalesce(?bd1, ?bd2) AS ?bdate)
  FILTER(?bdate = ?earliestBirth)
  OPTIONAL { ?film rdfs:label ?filmLabel. FILTER(lang(?filmLabel) = "en") }
  OPTIONAL { ?director rdfs:label ?directorLabel. FILTER(lang(?directorLabel) = "en") }
}
ORDER BY ?earliestBirth
LIMIT 1

